@if($pdfFile)<script type="module">
import * as pdfjsLib from 'https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs';
pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs';
const shell=document.querySelector('.reader-shell'), url=shell.dataset.pdfUrl, root=document.getElementById('pdfPages'), list=document.getElementById('pageList'), current=document.getElementById('currentPage'), total=document.getElementById('totalPages'), zoomValue=document.getElementById('zoomValue');
let pdf=null,scale=1,auto=false,autoTimer=null,speaking=false;
const renderPage=async n=>{const page=await pdf.getPage(n), viewport=page.getViewport({scale});let box=document.querySelector('[data-page="'+n+'"]');if(!box){box=document.createElement('div');box.className='pdf-page';box.dataset.page=n;const canvas=document.createElement('canvas');box.appendChild(canvas);root.appendChild(box);list.insertAdjacentHTML('beforeend','<button type="button" data-page="'+n+'">صفحه '+n+'</button>');list.lastElementChild.onclick=()=>document.querySelector('[data-page="'+n+'"]')?.scrollIntoView({behavior:'smooth',block:'start'})}const canvas=box.querySelector('canvas'),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.floor(viewport.width*dpr);canvas.height=Math.floor(viewport.height*dpr);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';await page.render({canvasContext:canvas.getContext('2d'),viewport,transform:[dpr,0,0,dpr,0,0]}).promise};
const renderAll=async()=>{root.innerHTML='';list.innerHTML='';const limit=shell.dataset.preview==='1'?Math.min(7,pdf.numPages):pdf.numPages;total.textContent=limit;for(let n=1;n<=limit;n++)await renderPage(n);};
pdfjsLib.getDocument({url,disableAutoFetch:false}).promise.then(async p=>{pdf=p;await renderAll();const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){current.textContent=e.target.dataset.page;list.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.page===e.target.dataset.page))}}),{threshold:.5});document.querySelectorAll('.pdf-page').forEach(x=>io.observe(x));}).catch(()=>{root.innerHTML='<div class="reader-empty"><strong>PDF Viewer نتوانست فایل Preview را باز کند.</strong><span>لطفاً بعداً دوباره تلاش کنید.</span></div>'});
document.querySelector('[data-action="zoom-in"]').onclick=async()=>{scale=Math.min(2,scale+.15);zoomValue.textContent=Math.round(scale*100)+'%';await renderAll()};document.querySelector('[data-action="zoom-out"]').onclick=async()=>{scale=Math.max(.7,scale-.15);zoomValue.textContent=Math.round(scale*100)+'%';await renderAll()};
document.querySelector('[data-action="theme"]').onclick=()=>shell.classList.toggle('theme-soft');document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{shell.classList.remove('theme-soft','theme-night');if(b.dataset.theme!=='paper')shell.classList.add('theme-'+b.dataset.theme)});
document.querySelector('[data-action="auto"]').onclick=()=>{auto=!auto;if(auto){autoTimer=setInterval(()=>window.scrollBy({top:1,left:0,behavior:'auto'}),35)}else clearInterval(autoTimer)};
document.querySelector('[data-action="speak"]').onclick=async()=>{if(!('speechSynthesis'in window))return;if(speaking){speechSynthesis.cancel();speaking=false;return}const n=Number(current.textContent||1),page=await pdf.getPage(n),text=await page.getTextContent(),utter=new SpeechSynthesisUtterance(text.items.map(x=>x.str).join(' '));utter.lang='fa-IR';utter.rate=.9;utter.onend=()=>speaking=false;speaking=true;speechSynthesis.cancel();speechSynthesis.speak(utter)};
</script>@else<script>
(()=>{const shell=document.querySelector('.reader-shell'),pages=[...document.querySelectorAll('.reader-page')],list=document.getElementById('pageList'),current=document.getElementById('currentPage');pages.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.dataset.page=p.dataset.page;b.textContent='صفحه '+p.dataset.page;b.onclick=()=>p.scrollIntoView({behavior:'smooth'});list.appendChild(b)});new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)current.textContent=e.target.dataset.page}),{threshold:.5}).observe(pages[0]);let auto=false,timer;document.querySelector('[data-action="auto"]').onclick=()=>{auto=!auto;if(auto)timer=setInterval(()=>scrollBy(0,1),35);else clearInterval(timer)};document.querySelector('[data-action="theme"]').onclick=()=>shell.classList.toggle('theme-soft');document.querySelector('[data-action="speak"]').onclick=()=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(document.querySelector('.reader-page')?.innerText||'');u.lang='fa-IR';u.rate=.9;speechSynthesis.speak(u)};})();
</script>@endif
